/*
 * A306108  Numbers with digits in {0,...,5} such that every other digit is
 *          strictly less than its neighbors.
 * https://oeis.org/A306108
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is generated by enumerating all decimal numbers * with
 *            digits from 0..5 such that every digit in an odd position *
 *            (0‑based from the left) is strictly less than its two neighbors.
 *            * The sequence is produced in increasing order
 * Range:     u8 n <= 35, u16 n <= 69, u32 n <= 69, u64 n <= 69, u128 n <= 69,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>

/* Cached terms of the sequence. */
static seq_t *seq_cache = NULL;
static size_t cache_len = 0;   /* number of terms stored */
static size_t cache_cap = 0;   /* allocated capacity */
static idx_t next_len_to_generate = 1;   /* next number of digits to generate */

/* Append a value to the cache, reallocating if necessary. */
static void push_seq(seq_t v) {
    if (cache_len >= cache_cap) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 64;
        seq_t *p = (seq_t *)realloc(seq_cache, new_cap * sizeof(seq_t));
        if (!p) abort();
        seq_cache = p;
        cache_cap = new_cap;
    }
    seq_cache[cache_len++] = v;
}

/* Recursive generator for numbers of a given length. */
static void generate_len_rec(int len, int pos, seq_t val, uint8_t last) {
    if (pos == len) {
        push_seq(val);
        return;
    }
    if (pos & 1) {               /* odd position: digit < left neighbor */
        for (int d = 0; d < last; ++d) {
            generate_len_rec(len, pos + 1, val * 10 + (seq_t)d, (uint8_t)d);
        }
    } else {                      /* even position (except first): digit > left neighbor */
        for (int d = last + 1; d <= 5; ++d) {
            generate_len_rec(len, pos + 1, val * 10 + (seq_t)d, (uint8_t)d);
        }
    }
}

/* Generate all numbers with exactly `len` digits that satisfy the rule. */
static void generate_len(int len) {
    if (len == 1) {               /* single‑digit numbers */
        for (int d = 0; d <= 5; ++d)
            push_seq((seq_t)d);
        return;
    }
    for (int d = 1; d <= 5; ++d)  /* first digit cannot be 0 (except len==1) */
        generate_len_rec(len, 1, (seq_t)d, (uint8_t)d);
}

/* Ensures that at least `n` terms are stored in the cache. */
static void ensure_terms(idx_t n) {
    while (cache_len < n) {
        generate_len(next_len_to_generate++);
    }
}

/* Public interface: a(n) for n>=1. */
seq_t a(idx_t n) {
    if (n < 1) return 0;          /* undefined for n<1, return 0 safely */
    ensure_terms(n);
    return seq_cache[n - 1];       /* offset 1 */
}
